async function walletApi(url, options = {}) {
  const response = await fetch(url, {
    ...options,
    credentials:'same-origin',
    headers:options.body ? { 'Content-Type':'application/json', ...(options.headers || {}) } : options.headers,
  });
  const data = await response.json().catch(() => ({}));
  if (response.status === 401) clearPlatformSession();
  if (!response.ok) throw new Error(data.error || '请求失败，请重试');
  return data;
}

function refreshWalletDependents() {
  if (typeof setTradeProduct === 'function') setTradeProduct(typeof tradeProduct === 'string' ? tradeProduct : 'perp');
  if (typeof renderTradeAccount === 'function') renderTradeAccount();
