  if (lockedText) lockedText.textContent = '连接钱包即可进入；首次资金操作时再核对一次钱包，无需邮箱或其他账号。';
  $('wallet-connect-btn').textContent = '连接钱包';
  $('wallet-connect-btn').classList.remove('connected');
