  if (!menu) return;
  const willOpen = menu.hidden;
  menu.hidden = !willOpen;
  if (button) button.setAttribute('aria-expanded', String(willOpen));
  if (willOpen) {
    // header 带 overflow-x:hidden，绝对定位下拉会被裁掉（手机上需滚动才可见）；
    // 改用 fixed 定位，实时锚定钱包按钮，确保菜单直接弹出在按钮下方。
